 private static final EnumMap<Kind,DeferredItem<MissileItem>> MISSILES=new EnumMap<>(Kind.class);private static final EnumMap<Kind,DeferredHolder<EntityType<?>,EntityType<Entity>>> TYPES=new EnumMap<>(Kind.class);
 static{for(var kind:Kind.values()){MISSILES.put(kind,ITEMS.register(kind.id,()->new MissileItem(kind.id,kind.form,kind.tier)));TYPES.put(kind,ENTITIES.register(kind.entityId,()->EntityType.Builder.<Entity>of((type,world)->kind.factory.apply(type,world),MobCategory.MISC).sized(1.5F,1.5F).clientTrackingRange(63).updateInterval(1).build("hbm:"+kind.entityId)));}}
 public static final DeferredHolder<EntityType<?>,EntityType<EntityEMP>> EMP=ENTITIES.register("entity_emp_logic",()->EntityType.Builder.<EntityEMP>of(EntityEMP::new,MobCategory.MISC).sized(.6F,1.8F).clientTrackingRange(63).updateInterval(1).build("hbm:entity_emp_logic"));
 public static void register(IEventBus bus){ITEMS.register(bus);ENTITIES.register(bus);bus.addListener(EmpMachineSparks::register);bus.addListener((RegisterTicketControllersEvent e)->e.register(EntityMissileAntiBallistic.TICKETS));com.hbm.missile.completion.volcano.VolcanoContent.register(bus);com.hbm.missile.launchpad.standard.StandardLaunchPadContent.register(bus);}
 public static DeferredItem<MissileItem> missile(Kind kind){return MISSILES.get(kind);}public static DeferredHolder<EntityType<?>,EntityType<Entity>> entity(Kind kind){return TYPES.get(kind);}public static Kind kind(ItemStack stack){for(var kind:Kind.values())if(stack.is(MISSILES.get(kind).get()))return kind;return null;}public static Kind kind(Entity entity){for(var kind:Kind.values())if(entity.getType()==TYPES.get(kind).get())return kind;return null;}
 public static EntityType<?> type(String id){for(var kind:Kind.values())if(kind.id.equals(id))return TYPES.get(kind).get();throw new IllegalArgumentException("Unknown actual missile "+id);}public static Item item(String id){for(var kind:Kind.values())if(kind.id.equals(id))return MISSILES.get(kind).get();var location=id(id);if(!BuiltInRegistries.ITEM.containsKey(location))throw new IllegalStateException("Missing actual missile component "+location);return BuiltInRegistries.ITEM.get(location);}
 public static List<ItemStack> creativeStacks(String tab){var result=new ArrayList<ItemStack>();if(tab.equals("missile"))for(var kind:Kind.values())if(kind!=Kind.TEST)result.add(new ItemStack(MISSILES.get(kind).get()));result.addAll(com.hbm.missile.completion.volcano.VolcanoContent.creativeStacks(tab));result.addAll(com.hbm.missile.launchpad.standard.StandardLaunchPadContent.creativeStacks(tab));return result;}public static ResourceLocation id(String path){return ResourceLocation.fromNamespaceAndPath("hbm",path);}private MissileContent(){}
